I18N.keep={"fr": {"piece.keep": "Garder le sens", "pieces.keepHint": "Coche « Garder le sens » pour le fil du bois, un placage ou une gravure orientée : la pièce ne sera pas tournée d’un quart de tour."}, "en": {"piece.keep": "Keep orientation", "pieces.keepHint": "Tick “Keep orientation” for wood grain, veneer or directional engraving: the part will not be turned a quarter turn."}, "de": {"piece.keep": "Richtung beibehalten", "pieces.keepHint": "Hake „Richtung beibehalten“ für Holzmaserung, Furnier oder ausgerichtete Gravur an: Das Teil wird nicht um eine Vierteldrehung gedreht."}, "es": {"piece.keep": "Mantener orientación", "pieces.keepHint": "Marca «Mantener orientación» para la veta de la madera, un chapado o un grabado orientado: la pieza no se girará un cuarto de vuelta."}, "pt": {"piece.keep": "Manter orientação", "pieces.keepHint": "Marque “Manter orientação” para o veio da madeira, lâmina ou gravação orientada: a peça não será girada um quarto de volta."}, "ru": {"piece.keep": "Сохранить направление", "pieces.keepHint": "Отметьте «Сохранить направление» для волокон дерева, шпона или ориентированной гравировки: деталь не будет поворачиваться на четверть оборота."}, "zh": {"piece.keep": "保持方向", "pieces.keepHint": "木纹、贴皮或有方向的雕刻请勾选“保持方向”：零件不会被旋转 90°。"}, "hi": {"piece.keep": "दिशा बनाए रखें", "pieces.keepHint": "लकड़ी के रेशे, विनियर या दिशा वाली नक्काशी के लिए “दिशा बनाए रखें” चुनें: पार्ट को चौथाई घुमाया नहीं जाएगा।"}, "bn": {"piece.keep": "দিক বজায় রাখুন", "pieces.keepHint": "কাঠের আঁশ, ভিনিয়ার বা দিকনির্ভর খোদাইয়ের জন্য “দিক বজায় রাখুন” বেছে নিন: পার্টটি এক-চতুর্থাংশ ঘোরানো হবে না।"}, "ar": {"piece.keep": "الحفاظ على الاتجاه", "pieces.keepHint": "فعّل «الحفاظ على الاتجاه» لعروق الخشب أو القشرة أو النقش الموجَّه: لن تُدار القطعة ربع دورة."}, "id": {"piece.keep": "Pertahankan arah", "pieces.keepHint": "Centang “Pertahankan arah” untuk serat kayu, veneer, atau ukiran berarah: komponen tidak akan diputar seperempat putaran."}, "it": {"piece.keep": "Mantieni il verso", "pieces.keepHint": "Spunta «Mantieni il verso» per la venatura del legno, un’impiallacciatura o un’incisione orientata: il pezzo non verrà ruotato di un quarto di giro."}, "nl": {"piece.keep": "Richting behouden", "pieces.keepHint": "Vink “Richting behouden” aan voor houtnerf, fineer of een gerichte gravure: het onderdeel wordt niet een kwartslag gedraaid."}, "pl": {"piece.keep": "Zachowaj kierunek", "pieces.keepHint": "Zaznacz „Zachowaj kierunek” dla słojów drewna, forniru lub ukierunkowanego graweru: element nie zostanie obrócony o ćwierć obrotu."}, "ro": {"piece.keep": "Păstrează orientarea", "pieces.keepHint": "Bifează „Păstrează orientarea” pentru fibra lemnului, furnir sau o gravură orientată: piesa nu va fi rotită cu un sfert de tură."}, "cs": {"piece.keep": "Zachovat směr", "pieces.keepHint": "Zaškrtni „Zachovat směr“ kvůli kresbě dřeva, dýze nebo orientované gravuře: díl se neotočí o čtvrt otáčky."}, "sk": {"piece.keep": "Zachovať smer", "pieces.keepHint": "Zaškrtni „Zachovať smer“ kvôli kresbe dreva, dyhe alebo orientovanému gravírovaniu: diel sa neotočí o štvrť otáčky."}, "hu": {"piece.keep": "Irány megtartása", "pieces.keepHint": "Jelöld be az „Irány megtartása” lehetőséget fa erezetnél, furnérnál vagy irányított gravírozásnál: az alkatrész nem fordul el negyed fordulattal."}, "sv": {"piece.keep": "Behåll riktning", "pieces.keepHint": "Kryssa i ”Behåll riktning” för träets fiberriktning, faner eller riktad gravering: detaljen vrids inte ett kvarts varv."}, "da": {"piece.keep": "Bevar retning", "pieces.keepHint": "Sæt flueben ved “Bevar retning” for træets årer, finer eller en retningsbestemt gravering: emnet drejes ikke en kvart omgang."}, "nb": {"piece.keep": "Behold retning", "pieces.keepHint": "Huk av «Behold retning» for treets fiberretning, finér eller retningsbestemt gravering: delen blir ikke dreid en kvart omdreining."}, "fi": {"piece.keep": "Säilytä suunta", "pieces.keepHint": "Valitse ”Säilytä suunta” puun syysuunnan, viilun tai suunnatun kaiverruksen vuoksi: osaa ei käännetä neljänneskierrosta."}, "el": {"piece.keep": "Διατήρηση κατεύθυνσης", "pieces.keepHint": "Τσέκαρε «Διατήρηση κατεύθυνσης» για νερά ξύλου, καπλαμά ή προσανατολισμένο χάραγμα: το κομμάτι δεν θα περιστραφεί κατά ένα τέταρτο."}, "bg": {"piece.keep": "Запази посоката", "pieces.keepHint": "Отметни „Запази посоката“ при шарка на дървото, фурнир или насочена гравюра: детайлът няма да се завърта на четвърт оборот."}, "hr": {"piece.keep": "Zadrži smjer", "pieces.keepHint": "Označi „Zadrži smjer” zbog žila drva, furnira ili usmjerene gravure: dio se neće okretati za četvrt kruga."}, "bs": {"piece.keep": "Zadrži smjer", "pieces.keepHint": "Označi „Zadrži smjer” zbog žila drveta, furnira ili usmjerene gravure: dio se neće okretati za četvrt kruga."}, "sl": {"piece.keep": "Ohrani smer", "pieces.keepHint": "Označi »Ohrani smer« zaradi lesnih vlaken, furnirja ali usmerjene gravure: del se ne bo zavrtel za četrt obrata."}, "sr": {"piece.keep": "Задржи смер", "pieces.keepHint": "Означи „Задржи смер” због влакана дрвета, фурнира или усмерене гравуре: део се неће окретати за четврт круга."}, "mk": {"piece.keep": "Задржи насока", "pieces.keepHint": "Означи „Задржи насока“ за влакната на дрвото, фурнир или насочена гравура: делот нема да се врти за четвртина круг."}, "sq": {"piece.keep": "Ruaj drejtimin", "pieces.keepHint": "Shëno “Ruaj drejtimin” për fijen e drurit, rimeson ose gdhendje me drejtim: pjesa nuk do të rrotullohet një çerek rrotullimi."}, "uk": {"piece.keep": "Зберегти напрям", "pieces.keepHint": "Позначте «Зберегти напрям» для волокон деревини, шпону або орієнтованого гравіювання: деталь не повертатиметься на чверть оберту."}, "be": {"piece.keep": "Захаваць напрамак", "pieces.keepHint": "Пазначце «Захаваць напрамак» для валокнаў дрэва, шпону або арыентаванай гравіроўкі: дэталь не будзе паварочвацца на чвэрць абароту."}, "lt": {"piece.keep": "Išlaikyti kryptį", "pieces.keepHint": "Pažymėk „Išlaikyti kryptį“ dėl medienos rievių, lukšto ar kryptinio graviravimo: detalė nebus pasukta ketvirčiu apsisukimo."}, "lv": {"piece.keep": "Saglabāt virzienu", "pieces.keepHint": "Atzīmē “Saglabāt virzienu” koksnes šķiedrām, finierim vai virzītam gravējumam: detaļa netiks pagriezta par ceturtdaļapgriezienu."}, "et": {"piece.keep": "Säilita suund", "pieces.keepHint": "Märgi „Säilita suund“ puidu kiu, spooni või suunatud graveeringu puhul: detaili ei pöörata veerandpööret."}, "ga": {"piece.keep": "Coinnigh an treo", "pieces.keepHint": "Cuir tic le “Coinnigh an treo” do shnáithe an adhmaid, veinír nó greanadh treoch: ní chasfar an píosa ceathrú casadh."}, "mt": {"piece.keep": "Żomm id-direzzjoni", "pieces.keepHint": "Immarka “Żomm id-direzzjoni” għall-ħjut tal-injam, il-fuljett jew inċiżjoni orjentata: il-biċċa mhux se ddur kwart ta’ dawra."}, "is": {"piece.keep": "Halda stefnu", "pieces.keepHint": "Hakaðu við „Halda stefnu“ vegna viðaræða, spóns eða stefnubundins leturgraftar: hlutnum verður ekki snúið um fjórðung."}, "lb": {"piece.keep": "Richtung behalen", "pieces.keepHint": "Kräiz „Richtung behalen“ un fir d’Holzfaser, Furnéier oder eng ausgeriicht Gravur: den Deel gëtt net ëm eng Véierelsdréiung gedréint."}, "ca": {"piece.keep": "Mantén l’orientació", "pieces.keepHint": "Marca «Mantén l’orientació» per a la veta de la fusta, un xapat o un gravat orientat: la peça no es girarà un quart de volta."}, "tr": {"piece.keep": "Yönü koru", "pieces.keepHint": "Ahşap lifi, kaplama ya da yönlü gravür için “Yönü koru”yu işaretle: parça çeyrek tur döndürülmez."}, "ja": {"piece.keep": "向きを固定", "pieces.keepHint": "木目・突板・向きのある彫刻には「向きを固定」をチェック：部品は 90° 回転されません。"}, "ko": {"piece.keep": "방향 유지", "pieces.keepHint": "나뭇결, 무늬목, 방향이 있는 각인에는 “방향 유지”를 선택하세요. 부품이 90° 회전되지 않습니다."}, "zh-Hant": {"piece.keep": "保持方向", "pieces.keepHint": "木紋、貼皮或有方向的雕刻請勾選「保持方向」：零件不會被旋轉 90°。"}, "th": {"piece.keep": "คงทิศทาง", "pieces.keepHint": "เลือก “คงทิศทาง” สำหรับลายเสี้ยนไม้ แผ่นวีเนียร์ หรืองานแกะสลักที่มีทิศทาง: ชิ้นงานจะไม่ถูกหมุน 90°"}};
Object.keys(I18N.keep).forEach(function(c){if(I18N.dict[c])Object.assign(I18N.dict[c],I18N.keep[c])});
